import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Automation","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Automation | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/automation"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Automation | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/automation"}]]},"headers":[],"relativePath":"user-guide/automation.md","filePath":"user-guide/automation.md","lastUpdated":1787271837000}'),n={name:"user-guide/automation.md"};function i(s,t,d,l,c,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h1><p>Workflow Automation lets your workspace react to CRM and operations events without custom code.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong> and install <strong>Automation</strong> (billable add-on).</li><li>Ensure your role includes Automation permissions (Admin gets full access by default).</li><li>Open <strong>Automation</strong> in the sidebar.</li></ol><h2 id="build-a-workflow" tabindex="-1">Build a workflow <a class="header-anchor" href="#build-a-workflow" aria-label="Permalink to &quot;Build a workflow&quot;">​</a></h2><ol><li><strong>New</strong> or pick a <strong>Template</strong>.</li><li>Choose a <strong>trigger</strong> (Lead created, Task completed, Manual, Schedule, …). Triggers for modules you have not installed are unavailable.</li><li>Add optional <strong>conditions</strong> (field / operator / value; AND or OR groups).</li><li>Add one or more <strong>actions</strong> in order (create task, notify, webhook, …).</li><li><strong>Save</strong> (inactive) or <strong>Save &amp; activate</strong>. Only active workflows run. Triggers marked <strong>Coming soon</strong> can be saved but not activated.</li></ol><h3 id="triggers-v1" tabindex="-1">Triggers (v1) <a class="header-anchor" href="#triggers-v1" aria-label="Permalink to &quot;Triggers (v1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>When</th></tr></thead><tbody><tr><td>Manual</td><td>You click Run</td></tr><tr><td>Schedule</td><td>Daily / weekly / monthly / cron (workspace timezone)</td></tr><tr><td>Lead created / updated / assigned</td><td>Lead lifecycle</td></tr><tr><td>Task created / completed / assigned</td><td>Task lifecycle</td></tr><tr><td>Opportunity created / stage changed / assigned</td><td>Pipeline</td></tr><tr><td>Meeting created / completed</td><td>Meetings</td></tr><tr><td>Customer invoice created</td><td>Invoicing</td></tr></tbody></table><p>Some catalog entries may show as “coming soon” until their bridge ships; you cannot activate those yet.</p><h3 id="actions-v1" tabindex="-1">Actions (v1) <a class="header-anchor" href="#actions-v1" aria-label="Permalink to &quot;Actions (v1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>Create task</td><td>Requires Tasks module</td></tr><tr><td>Create note</td><td>On lead / task / opportunity from the triggering entity</td></tr><tr><td>Assign user</td><td>Sets assignee on the entity</td></tr><tr><td>Add / remove tag</td><td>Lead or task tags</td></tr><tr><td>Update field</td><td>Allowlisted fields only</td></tr><tr><td>Move stage</td><td>Opportunity (and Lead stage when applicable)</td></tr><tr><td>Send notification</td><td>In-app; <code>source=workflow</code></td></tr><tr><td>Webhook</td><td>Signed outbound HTTP POST</td></tr><tr><td>Delay</td><td>Wait before the next step</td></tr></tbody></table><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>Use <strong>Templates</strong> to seed a draft workflow (inactive). Edit conditions/actions, then activate.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><p><strong>Runs</strong> shows each execution with status and step logs. Failures keep an error message for troubleshooting. Manual <strong>Run</strong> is useful for testing.</p><h2 id="coexistence-with-built-in-lead-rules" tabindex="-1">Coexistence with built-in Lead rules <a class="header-anchor" href="#coexistence-with-built-in-lead-rules" aria-label="Permalink to &quot;Coexistence with built-in Lead rules&quot;">​</a></h2><p>Lead tag auto follow-ups and inactivity digests remain hard-coded product rules. They are <strong>not</strong> replaced by Automation in v1 — you can use both.</p><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Schedule triggers use the workspace timezone from <strong>Settings → General</strong>. Absolute timestamps in run logs follow the same convention as other modules.</p>',19)])])}const m=e(n,[["render",i]]);export{h as __pageData,m as default};
